/** Build the fixed twelve-verifier set. The original ten unchanged compiled
 * artifacts are copied only after source/key/compiler identity checks; only
 * the revised admission and new deposit-intent verifier are compiled here.
 * No key, proof, EVM runtime or native transfer is generated by this task. */
import assert from 'node:assert/strict';
import { readFileSync, realpathSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { ROOT, LOCAL, relation } from '@lianum/proofs/catalog';
import { assertID, regular, hash, writeJSON, writeNew, replaceJSON, resourceModuleURL,
  circuitIdentity, versionDirectory, loadCompiled, loadPrepared } from '@lianum/proofs/tooling/tooling';
import { compileSoliditySources } from '@lianum/proofs/tooling/solidity-compiler';
import { integrationSourcePins } from '../../runners/source-pins.mjs';
import { nativeSystemSources } from '../../../../packages/backend/src/execution/native/dispatch/native-deployment.mjs';
import { deriveGenericVerifierImmutables } from '@lianum/engine/execution/local/local-deployment';
import { loadProofProfile } from '@lianum/proofs/execution/proof-worker';

assert.equal(process.argv.length, 3, 'VERIFIER_FIXED_ARGS');
assert.deepEqual(process.execArgv, [], 'VERIFIER_NO_EXEC_OPTIONS');
assert.deepEqual(Object.keys(process.env).sort(), ['LANG', 'PATH'], 'VERIFIER_CLEAN_ENV');
const runId = assertID(process.argv[2]), attempt = join(LOCAL, 'verifier-compilation', runId);
const parentArgs = readFileSync(`/proc/${process.ppid}/cmdline`, 'utf8').split('\0').filter(Boolean);
assert.equal(parentArgs.length, 2, 'VERIFIER_PARENT_ARGS');
assert.equal(realpathSync(`/proc/${process.ppid}/exe`), realpathSync(process.execPath), 'VERIFIER_PARENT_EXE');
assert.equal(realpathSync(resolve(realpathSync(`/proc/${process.ppid}/cwd`), parentArgs[1])),
  join(ROOT, 'integration/run-verifier-compilation.mjs'), 'VERIFIER_PARENT_SCRIPT');
assert.equal(realpathSync(process.argv[1]), join(ROOT, 'integration/verifier-compilation-worker.mjs'), 'VERIFIER_WORKER_SCRIPT');
const lock = JSON.parse(regular(join(LOCAL, 'verifier-compilation.lock')));
assert.equal(lock.runId, runId); assert.equal(lock.pid, process.ppid);
const supervisor = JSON.parse(regular(join(attempt, 'resources.json')));
assert.deepEqual(integrationSourcePins('verifiers'), supervisor.sourcePins, 'VERIFIER_SOURCE_FREEZE');
const result = { format: 'FLAT_GENERATED_VERIFIER_COMPILATION_V1', runId, phase: 'loading',
  classification: 'ACTUAL_KEY_SOURCES_COMPILED_NOT_DEPLOYED_OR_PROOF_ACCEPTED',
  startedAt: new Date().toISOString(), sourcePins: supervisor.sourcePins, contracts: [],
  keyGenerated: false, proofGenerated: false, nativeNodesStarted: false };
const save = () => replaceJSON(join(attempt, 'result.json'), result);
const phase = value => { result.phase = value; save(); };
const began = performance.now();
const summaries = [];
const REUSE_RUN = 'dd3bcf1a-e713-41db-8c38-fd04fa7e88e7';
const REUSE_RESULT_SHA256 = '82fc661b5629b1a34e1bd6f51437097f2409c27b6cced2703d5200af35c0ae93';
const REUSE_RESOURCES_SHA256 = 'b780c6daf25cc2af62e98c5b303983afb0b3279dd4c5f2ef8c092c627aae450a';
const REUSE_ROLES = new Set(['authorization', 'reservation', 'dependency', 'ready',
  'node', 'settlement', 'recovery', 'deposit_balance', 'withdraw_balance', 'withdraw_output']);

function retainedCompilation(input, toolchain, crs) {
  if (!REUSE_ROLES.has(input.name)) return null;
  const directory = join(LOCAL, 'verifier-compilation', REUSE_RUN);
  const bytes = regular(join(directory, 'result.json'));
  const resources = regular(join(directory, 'resources.json'));
  assert.equal(hash(bytes), REUSE_RESULT_SHA256, 'VERIFIER_REUSE_RESULT_PIN');
  assert.equal(hash(resources), REUSE_RESOURCES_SHA256, 'VERIFIER_REUSE_RESOURCES_PIN');
  const previous = JSON.parse(bytes), monitor = JSON.parse(resources);
  assert.equal(previous.phase, 'completed'); assert.equal(monitor.phase, 'completed');
  assert.equal(monitor.exitCode, 0); assert.deepEqual(monitor.failures, []);
  assert.deepEqual(previous.toolchain, toolchain, 'VERIFIER_REUSE_TOOLCHAIN');
  assert.deepEqual(previous.crs, crs, 'VERIFIER_REUSE_CRS');
  const rows = previous.contracts.filter(row => row.relation === input.name);
  assert.equal(rows.length, 1, 'VERIFIER_REUSE_ROLE');
  const row = rows[0], roleDirectory = join(directory, input.name);
  assert.equal(row.publicWords, input.publicWords, 'VERIFIER_REUSE_WIDTH');
  assert.equal(row.sourceSHA256, hash(input.content), 'VERIFIER_REUSE_CURRENT_SOURCE');
  assert.deepEqual(row.lineage, input.lineage, 'VERIFIER_REUSE_CURRENT_KEY_LINEAGE');
  assert.deepEqual(JSON.parse(regular(join(roleDirectory, 'manifest.json'))), row);
  assert.equal(regular(join(roleDirectory, input.name + '.sol')).toString('utf8'), input.content);
  const compiledBytes = regular(join(roleDirectory, 'compiled.json'));
  assert.equal(hash(compiledBytes), row.compiledSHA256, 'VERIFIER_REUSE_COMPILED_PIN');
  const compiled = JSON.parse(compiledBytes);
  assert.equal(compiled.profile, 'verifier');
  assert.deepEqual(compiled.compiler, row.compiler); assert.deepEqual(compiled.settings, row.settings);
  return { compiled, compiledBytes, provenance: { runId: REUSE_RUN,
    resultSHA256: REUSE_RESULT_SHA256, resourcesSHA256: REUSE_RESOURCES_SHA256,
    originalCompiledSHA256: row.compiledSHA256, originalCompilationMilliseconds: row.milliseconds } };
}
function immutableNames(ast) {
  const names = {};
  function visit(value) {
    if (!value || typeof value !== 'object') return;
    if (value.nodeType === 'VariableDeclaration' && value.mutability === 'immutable') names[value.id] = value.name;
    for (const child of Object.values(value)) {
      if (Array.isArray(child)) child.forEach(visit); else if (child && typeof child === 'object') visit(child);
    }
  }
  visit(ast); return names;
}
try {
  save();
  const helpers = await import(resourceModuleURL);
  const toolchain = helpers.verifyToolchain(), crs = helpers.verifyCRS();
  result.toolchain = toolchain; result.crs = crs;
  const inputs = [];
  for (const name of ['authorization', 'reservation', 'dependency', 'ready', 'admission', 'node', 'settlement', 'recovery']) {
    const spec = relation(name), identity = circuitIdentity(spec, toolchain), sourceVersion = hash(JSON.stringify(identity));
    const context = { spec, toolchain, identity, sourceVersion, directory: versionDirectory(spec, sourceVersion) };
    const compiled = await loadCompiled(context), prepared = await loadPrepared(context, compiled, crs);
    inputs.push({ name, content: prepared.solidity.toString('utf8'), publicWords: spec.publicWords,
      keyHashField: prepared.manifest.keyHashField, lineage: { sourceVersion,
        compiledManifestSHA256: compiled.manifestSHA256, keyManifestSHA256: prepared.manifestSHA256,
        keySHA256: hash(prepared.key), soliditySHA256: hash(prepared.solidity),
        keyBytes: prepared.key.length, originalMeasuredNodeReused: name === 'node' } });
  }
  const golden = await nativeSystemSources();
  for (const [name, mode, publicWords] of [['deposit_balance', 'deposit_balance', 26],
    ['withdraw_balance', 'withdraw_balance', 39], ['withdraw_output', 'withdraw', 39]]) {
    const source = golden[mode];
    assert.equal(hash(source.content), source.sha256, 'VERIFIER_GOLDEN_SOURCE_PIN');
    let lineage = { soliditySHA256: source.sha256, reuse: 'EXACT_GOLDEN_V17_SOURCE' };
    if (mode !== 'withdraw') {
      const loaded = loadProofProfile(mode);
      assert.equal(loaded.target, 'evm', 'VERIFIER_LEGACY_TARGET');
      assert.equal(loaded.publicPins.statementWords, publicWords, 'VERIFIER_LEGACY_WORDS');
      assert.equal(loaded.publicPins.soliditySHA256, source.sha256, 'VERIFIER_LEGACY_KEY_LINEAGE');
      lineage = { ...lineage, ...loaded.publicPins };
    } else {
      lineage.acceptanceReference = 'Golden v17 recipient and recovery exits; original output-note verifier source unchanged';
    }
    inputs.push({ name, content: source.content, publicWords, lineage });
  }
  {
    const name = 'deposit_intent', spec = relation(name), identity = circuitIdentity(spec, toolchain);
    const sourceVersion = hash(JSON.stringify(identity));
    const context = { spec, toolchain, identity, sourceVersion, directory: versionDirectory(spec, sourceVersion) };
    const compiled = await loadCompiled(context), prepared = await loadPrepared(context, compiled, crs);
    inputs.push({ name, content: prepared.solidity.toString('utf8'), publicWords: spec.publicWords,
      keyHashField: prepared.manifest.keyHashField, lineage: { sourceVersion,
        compiledManifestSHA256: compiled.manifestSHA256, keyManifestSHA256: prepared.manifestSHA256,
        keySHA256: hash(prepared.key), soliditySHA256: hash(prepared.solidity), keyBytes: prepared.key.length,
        originalMeasuredNodeReused: false } });
  }
  assert.equal(inputs.length, 12, 'VERIFIER_FIXED_ROLE_COUNT');
  for (const input of inputs) {
    const retained = retainedCompilation(input, toolchain, crs);
    phase((retained ? 'reusing-' : 'compiling-') + input.name);
    const filename = input.name + '.sol';
    const source = { content: input.content, sha256: hash(input.content) };
    writeNew(join(attempt, input.name, filename), input.content);
    const compiled = retained?.compiled ?? compileSoliditySources({ [filename]: source }, { profile: 'verifier' });
    const ast = compiled.sourceASTs[filename];
    const artifact = compiled.contracts[filename].HonkVerifier;
    assert.ok(artifact, 'VERIFIER_HONK_REQUIRED');
    const method = artifact.abi.filter(item => item.type === 'function' && item.name === 'verify');
    assert.equal(method.length, 1, 'VERIFIER_EXACT_VERIFY_METHOD');
    assert.deepEqual(method[0].inputs.map(item => item.type), ['bytes', 'bytes32[]'], 'VERIFIER_METHOD_INPUTS');
    assert.deepEqual(method[0].outputs.map(item => item.type), ['bool'], 'VERIFIER_METHOD_OUTPUT');
    assert.equal(method[0].stateMutability, 'view', 'VERIFIER_VIEW');
    const immutables = deriveGenericVerifierImmutables(ast, input.publicWords);
    if (input.keyHashField !== undefined)
      assert.equal(BigInt(immutables.$VK_HASH), BigInt(input.keyHashField), 'VERIFIER_ACTUAL_VK_HASH');
    const artifacts = Object.entries(compiled.contracts[filename]).map(([name, item]) => ({
      name, runtimeBytes: item.evm.deployedBytecode.object.length / 2,
      creationBytes: item.evm.bytecode.object.length / 2,
      runtimeHexTemplateSHA256: hash(item.evm.deployedBytecode.object),
      links: item.evm.bytecode.linkReferences,
    }));
    assert.ok(artifacts.every(item => item.runtimeBytes <= 24576 && item.creationBytes <= 49152),
      'VERIFIER_STANDARD_EVM_SIZE_LIMIT');
    if (retained) writeNew(join(attempt, input.name, 'compiled.json'), retained.compiledBytes);
    else writeJSON(join(attempt, input.name, 'compiled.json'), compiled);
    const summary = { relation: input.name, source: filename, publicWords: input.publicWords,
      lineage: input.lineage, sourceSHA256: source.sha256, compiler: compiled.compiler,
      settings: compiled.settings, milliseconds: retained ? 0 : compiled.milliseconds,
      compilationAction: retained ? 'REUSED_EXACT_RETAINED_COMPILATION' : 'COMPILED_CHANGED_SOURCE',
      reuse: retained?.provenance ?? null,
      immutableNames: immutableNames(ast), immutableValues: immutables, artifacts,
      compiledSHA256: hash(regular(join(attempt, input.name, 'compiled.json'))) };
    writeJSON(join(attempt, input.name, 'manifest.json'), summary);
    summaries.push(summary); result.contracts = summaries; save();
  }
  assert.deepEqual(integrationSourcePins('verifiers'), result.sourcePins, 'VERIFIER_SOURCE_CHANGED');
  assert.deepEqual(helpers.verifyCRS(), crs, 'VERIFIER_CRS_CHANGED');
  phase('completed');
} catch (error) {
  result.phase = 'failed'; result.errorCode = String(error.message).match(/\b(?:VERIFIER|SOLIDITY|PW|GENERIC|NATIVE)_[A-Z0-9_]+\b/)?.[0]
    ?? 'VERIFIER_COMPILATION_FAILED';
  if (error.compilerErrors) result.compilerErrors = error.compilerErrors.map(item => ({
    type: item.type, severity: item.severity, code: item.errorCode, message: item.formattedMessage }));
  process.exitCode = 1;
} finally {
  result.completedAt = new Date().toISOString(); result.milliseconds = performance.now() - began;
  result.resourceUsage = process.resourceUsage(); save();
}
